const p = $json;
const clamp = n => Math.max(0, Math.min(100, n));

let title = 40;
if (p.title.length >= 80 && p.title.length <= 200) title += 25; else if (p.title.length >= 40) title += 12;
const words = p.title.trim().split(/\s+/).filter(Boolean).length;
if (words >= 8) title += 15; else if (words >= 5) title += 8;
if (p.title.toLowerCase().includes((p.brandName||'').toLowerCase())) title += 10;
if (/\d/.test(p.title)) title += 10;
title = clamp(title);

const bullets = p.bulletPoints.length === 0 ? 0 : clamp(20 + Math.min(p.bulletPoints.length,5)*10 + (p.bulletPoints.some(b=>/benefit|help|easy|comfort|durable|quality/i.test(b)) ? 10 : 0));
const description = !p.description ? 0 : clamp(20 + (p.description.length>=400?35:p.description.length>=150?20:0) + (/guarantee|warranty|certified|satisfaction/i.test(p.description)?15:0) + (/use|care|instructions|maintain/i.test(p.description)?15:0));
const images = (p.images||[]).length === 0 ? 0 : clamp(10 + 15 + Math.min(p.images.length,7)*6);
const conversion = clamp(15 + (p.rating>=4.5?25:p.rating>=4.0?18:p.rating>=3.5?8:0) + (p.reviewCount>=500?20:p.reviewCount>=100?14:p.reviewCount>=20?6:0) + (/guarantee|warranty|certified/i.test(p.description||'')?20:0));
const competition = clamp(40 + 20);
const seo = Math.round((title*0.4 + bullets*0.35 + description*0.25)*100)/100;
const overall = Math.round((seo*0.25 + title*0.10 + bullets*0.10 + description*0.05 + images*0.25 + conversion*0.15 + competition*0.10)*100)/100;

return { json: { ...p, scores: { seo, title, bullets, description, images, conversion, competition }, overall_score: overall } };

const p = $json; const s = p.scores; const issues = [];
if (s.images === 0) issues.push({ category:'IMAGES', severity:'CRITICAL', title:'No product images found', description:'This listing has no images on record.', evidence: 'image count = 0', recommendation:'Upload at least 6 images including a main, infographic, and lifestyle shot.', confidence: 0.95 });
if (s.title < 50) issues.push({ category:'TITLE', severity: s.title<30?'HIGH':'MEDIUM', title:'Title is not optimized', description:`Title scored ${s.title}/100.`, evidence: `title = "${p.title}"`, recommendation:'Front-load keywords and include the brand name within 150-200 characters.', confidence: 0.75 });
if (s.bullets < 50) issues.push({ category:'BULLETS', severity: p.bulletPoints.length===0?'CRITICAL':'MEDIUM', title: p.bulletPoints.length===0?'No bullet points found':'Bullets lack benefit language', description:`Bullets scored ${s.bullets}/100.`, evidence: (p.bulletPoints||[]).join(' | ') || 'no bullet points', recommendation:'Use all 5 bullet slots with benefit-first, capitalized leads.', confidence: 0.75 });
if (s.description < 50) issues.push({ category:'DESCRIPTION', severity: !p.description?'HIGH':'MEDIUM', title: !p.description?'No product description found':'Description is thin or missing structure', description:`Description scored ${s.description}/100.`, evidence: p.description ? p.description.slice(0,140) : 'no description', recommendation:'Expand the description to 400+ characters and mention warranty/guarantee details.', confidence: 0.7 });
if (s.conversion < 50) issues.push({ category:'CONVERSION', severity:'MEDIUM', title:'Weak conversion signals', description:`Conversion scored ${s.conversion}/100.`, evidence: `rating=${p.rating ?? 'n/a'}, reviews=${p.reviewCount ?? 0}`, recommendation:'Highlight differentiation and add explicit trust signals.', confidence: 0.65 });
if (s.seo < 50) issues.push({ category:'SEO', severity:'MEDIUM', title:'Keyword coverage appears limited', description:`SEO scored ${s.seo}/100.`, evidence: 'derived from title/bullet/description component scores', recommendation:'Run a keyword gap analysis against top competitors.', confidence: 0.6 });
return { json: { ...p, issues } };
